inline const WideScreenProfile131* WideScreenProfileFor131(unsigned build){for(const auto& p:wideScreenProfiles131)if(p.build==build)return &p;return nullptr;}
// The optional five bytes are the owned MinHook entry, captured after enable.
inline bool WideScreenCode131(uintptr_t base,const WideScreenProfile131& p,const unsigned char* patch=nullptr){if(!base)return false;__try{for(size_t n=0;n<p.count;++n){const auto& c=p.code[n];unsigned char expected[512];if(c.length>sizeof(expected))return false;memcpy(expected,c.bytes,c.length);for(size_t j=0;j<c.relocCount;++j){const auto off=c.reloc[j];if(off+4>c.length)return false;unsigned value=0;memcpy(&value,expected+off,4);value+=unsigned(base);memcpy(expected+off,&value,4);}if(patch&&c.rva==p.projection){if(c.length<5)return false;memcpy(expected,patch,5);}if(memcmp(reinterpret_cast<void*>(base+c.rva),expected,c.length))return false;}return true;}__except(1){return false;}}
inline bool WideScreenArguments131(float fov,float aspect,float nearZ,float farZ){return std::isfinite(fov)&&std::isfinite(aspect)&&std::isfinite(nearZ)&&std::isfinite(farZ)&&fov>0.f&&fov<3.14159265358979323846f&&aspect>0.f&&nearZ>0.f&&farZ>nearZ;}
inline bool WideScreenDivisor131(long width,long height,float& divisor){if(width<=0||height<=0)return false;const float value=(float(width)/float(height))/(4.f/3.f);if(!std::isfinite(value)||value<=0.f)return false;divisor=value;return true;}
inline bool ApplyWideScreenMatrix131(float* output,float fov,float aspect,float nearZ,float farZ,float divisor){if(!output||!WideScreenArguments131(fov,aspect,nearZ,farZ)||!std::isfinite(divisor)||divisor<=0.f)return false;__try{float m[16];memcpy(m,output,sizeof(m));for(float value:m)if(!std::isfinite(value))return false;if(m[0]<=0.f||m[5]<=0.f||m[11]!=1.f||m[15]!=0.f)return false;for(unsigned index:{1u,2u,3u,4u,6u,7u,8u,9u,12u,13u})if(m[index]!=0.f)return false;const float value=m[0]/divisor;if(!std::isfinite(value)||value<=0.f)return false;output[0]=value;return true;}__except(1){return false;}}
using WideScreenNative131=void(__cdecl*)(float,float,float,float,float*);
inline WideScreenNative131 originalWideScreen131=nullptr;
inline std::atomic<bool> wideScreenActive131{false};
inline std::atomic<float> wideScreenDivisorValue131{1.f};
inline uintptr_t wideScreenBase131=0;inline unsigned wideScreenBuild131=0;inline bool wideScreenReady131=false;
inline unsigned char wideScreenPatch131[5]{};
inline void __cdecl WideScreenHook131(float fov,float aspect,float nearZ,float farZ,float* output){originalWideScreen131(fov,aspect,nearZ,farZ,output);if(wideScreenActive131.load(std::memory_order_acquire))ApplyWideScreenMatrix131(output,fov,aspect,nearZ,farZ,wideScreenDivisorValue131.load(std::memory_order_relaxed));}
inline bool WideScreenOwnedEntry131(uintptr_t target){if(!target)return false;__try{const auto* code=reinterpret_cast<const unsigned char*>(target);if(code[0]!=0xe9)return false;const auto destination=target+5+*reinterpret_cast<const int32_t*>(code+1);
#ifdef _WIN64
 const unsigned char relay[]={0xff,0x25,0,0,0,0};return !memcmp(reinterpret_cast<const void*>(destination),relay,sizeof(relay))&&*reinterpret_cast<const uintptr_t*>(destination+6)==reinterpret_cast<uintptr_t>(WideScreenHook131);
#else
 return destination==reinterpret_cast<uintptr_t>(WideScreenHook131);
#endif
 }__except(1){return false;}}
inline bool InstallWideScreen131(uintptr_t base,unsigned build){const auto* p=WideScreenProfileFor131(build);if(!p)return false;if(wideScreenReady131)return base==wideScreenBase131&&build==wideScreenBuild131&&WideScreenOwnedEntry131(base+p->projection)&&WideScreenCode131(base,*p,wideScreenPatch131);if(!WideScreenCode131(base,*p))return false;const auto init=MH_Initialize();if(init!=MH_OK&&init!=MH_ERROR_ALREADY_INITIALIZED)return false;void* target=reinterpret_cast<void*>(base+p->projection);if(MH_CreateHook(target,reinterpret_cast<void*>(WideScreenHook131),reinterpret_cast<void**>(&originalWideScreen131))!=MH_OK)return false;if(MH_EnableHook(target)!=MH_OK){MH_RemoveHook(target);originalWideScreen131=nullptr;return false;}memcpy(wideScreenPatch131,target,5);wideScreenBase131=base;wideScreenBuild131=build;wideScreenReady131=true;return WideScreenOwnedEntry131(base+p->projection)&&WideScreenCode131(base,*p,wideScreenPatch131);}
inline void ResetWideScreen131(){wideScreenActive131.store(false,std::memory_order_release);}
// Graphics eligibility depends on the live world/player, not resource balances.
inline bool WideScreenWorld131(uintptr_t base,unsigned build){const auto* p=ResourceProfileFor131(build);if(!p||!ResourceCode131(base,*p))return false;__try{unsigned local=24;const auto world=ResourceWorld131(base,*p,local);if(!world||local>=24)return false;const auto getPlayer=reinterpret_cast<uintptr_t(__thiscall*)(uintptr_t,unsigned)>(base+p->playerFn);const auto player=getPlayer(world,local);if(!ResourceIdentity131(player,base,p->playerTable)||*reinterpret_cast<int*>(player+p->statusOffset)!=1||*reinterpret_cast<unsigned char*>(player+p->idOffset)>=24)return false;unsigned check=24;return ResourceWorld131(base,*p,check)==world&&check==local&&getPlayer(world,local)==player&&*reinterpret_cast<int*>(player+p->statusOffset)==1;}__except(1){return false;}}
inline bool UpdateWideScreen131(uintptr_t base,unsigned build,HWND window,bool allowed,bool wanted){if(!allowed||!wanted){ResetWideScreen131();return true;}if(!WideScreenWorld131(base,build)){ResetWideScreen131();return true;}RECT rect{};float divisor=1.f;if(!GetClientRect(window,&rect)||!WideScreenDivisor131(rect.right-rect.left,rect.bottom-rect.top,divisor)||!InstallWideScreen131(base,build)){ResetWideScreen131();return false;}wideScreenDivisorValue131.store(divisor,std::memory_order_relaxed);wideScreenActive131.store(true,std::memory_order_release);return true;}
inline bool ParseWideScreen131(const std::wstring& args,bool current,bool& desired){if(args.find(L'\0')!=args.npos||args.find_first_of(L"\r\n")!=args.npos)return false;std::wistringstream in(args);std::wstring token,extra;desired=!current;if(!(in>>token))return true;if((token!=L"0"&&token!=L"1")||in>>extra)return false;desired=token==L"1";return true;}
template<class Ensure,class Save,class Reload> bool WideScreenSetting131(const std::wstring& args,bool& current,bool allowed,Ensure ensure,Save save,Reload reload,std::string& report){bool desired=false;if(!ParseWideScreen131(args,current,desired)){report="Usage: #wide [0|1]";return false;}if(desired&&(!allowed||!ensure())){report="Wide Screen: native hook unavailable or settings disabled";return false;}if(current!=desired){if(!save(desired)){report="Wide Screen: setting could not be saved";return false;}reload();if(current!=desired){report="Wide Screen: saved value was not loaded";return false;}}report=desired?"Wide Screen: ON (applies in an active match)":"Wide Screen: OFF";return true;}
